"""Researched acceptance productions. Content fixtures, not separate renderers."""
import sys,copy
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from engine.common import ROOT,read_json,write_json
from engine.history_schema import validate_document,year_label

def source(id,title,url,use):return dict(id=id,title=title,url=url,use=use,consulted='2026-09-03',evidence_status='consulted')
def loc(id,name,x,y,**kw):return dict(id=id,name=name,pos=[x,y],**kw)
def scene(id,title,kind,years,text,sources,**kw):
    lines=text.split('|')
    return dict(id=f'{id:02}',title=title,scene_type=kind,historical_range=years,date=year_label(years[0]) if years[0]==years[1] else year_label(years[0])+' – '+year_label(years[1]),lines=lines,sources=sources,**kw)
def event(id,year,title,kind,src,**kw):return dict(id=id,year=year,title=title,description=title,type=kind,sources=src,certainty='established',**kw)
def base(slug,title,kind,years,minutes,sources,places):
    return dict(schema_version=2,slug=slug,title=title,short_title=title.split(' — ')[0],documentary_type=kind,historical_period=dict(start=years[0],end=years[1],calendar='anni storici senza anno zero'),target_minutes=minutes,locations=places,sources=sources,persons=[],entities=[],events=[],scenes=[],visual_layers=[],visual_assets=[],metadata=dict(authoring='Ricerca e sintesi editoriale assistita; fixture di accettazione verificata.',status='researched'),editorial_notes=['Date dei processi diffuse nel tempo: le scansioni delle scene servono alla narrazione, non descrivono trasformazioni istantanee.','Coordinate di città attuali per orientamento; connessioni e regioni esplicitamente schematiche. Nessuna quantità è dedotta dallo spessore dei flussi.'],source_method='Pagine di musei, biblioteche, istituzioni e opere storiche consultate il 3 settembre 2026. Distinzione fra fatti, stime e interpretazioni nei dati e nelle note. Narrazione originale.',territorial_note='La cartografia fisica è moderna. Aree schematiche e reti non sono confini politici misurati.',map_notice='Mappe illustrative su base fisica moderna; reti schematiche e date dei processi indicative.',fps=24)

def renaissance():
    src=[source('R1','V&A — Donatello’s Florence','https://www.vam.ac.uk/articles/donatellos-florence','Firenze, cantieri, contesto urbano e committenze; interpretazione del rapporto fra città e arte.'),source('R2','Met — Painting in Oil in the Low Countries','https://www.metmuseum.org/essays/painting-in-oil-in-the-low-countries-and-its-spread-to-southern-europe','Tecnica a olio e circolazione dal Nord verso il Sud; evita il mito di una diffusione unidirezionale.'),source('R3','Met — A Goldsmith in his Shop','https://www.metmuseum.org/art/collection/search/459052','Petrus Christus, 1449; descrizione visiva originale. Identificazione del committente controversa, non asserita.'),source('R4','Library of Congress — Gutenberg Bible','https://www.loc.gov/item/2021666734/','Magonza e stampa a metà Quattrocento; la stima della tiratura dipende da una testimonianza, non usata come conteggio esatto.'),source('R5','Met — Venice and Northern Italy, 1400–1600','https://82nd-and-fifth.metmuseum.org/toah/ht/08/eustn.html','Prima stampa a Venezia nel 1469; tipografi provenienti dal Nord e sviluppo editoriale.'),source('R6','Met — Albrecht Dürer (1471–1528)','https://www.metmuseum.org/essays/albrecht-durer-1471-1528','Norimberga; viaggi italiani 1494–95 e 1505–07; diffusione delle stampe.'),source('R7','Met — Adam and Eve','https://www.metmuseum.org/art/collection/search/336222','Incisione del 1504, tecnica e soggetto. Riproduzione in pubblico dominio.'),source('R8','Château d’Amboise — Histoire du château','https://www.chateau-amboise.com/lhistoire-du-chateau/','Leonardo al Clos Lucé nel 1516–1519, invito di Francesco I e attività di corte.'),source('R9','Met — Erasmus of Rotterdam','https://www.metmuseum.org/art/collection/search/459080','Ritratto di Holbein e bottega circa 1532; lettere di presentazione del 1526. Nascita di Erasmo non certa: 1466/1469.'),source('R10','Met — The Renaissance of Etching','https://www.metmuseum.org/exhibitions/listings/2019/renaissance-of-etching','Trasferimento della tecnica dalle armature alle stampe; centri tedeschi, fiamminghi, italiani e francesi.'),source('R11','Met — Italian Renaissance Frames','https://www.metmuseum.org/essays/italian-renaissance-frames','Legame delle opere con gli ambienti originari e con la funzione, non immagini isolate.')]
    places=[loc('florence','Firenze',11.2558,43.7696),loc('venice','Venezia',12.3155,45.4408,offset=[55,20]),loc('rome','Roma',12.4964,41.9028),loc('bruges','Bruges',3.2247,51.2093),loc('mainz','Magonza',8.2473,49.9929),loc('nuremberg','Norimberga',11.0767,49.4521),loc('basel','Basilea',7.5886,47.5596),loc('amboise','Amboise',.984,47.413),loc('london','Londra',-.1276,51.5072)]
    d=base('rinascimento','Rinascimento — Un’Europa di scambi','cultural_movement',[1400,1550],6,src,places);d['short_title']='Rinascimento';d['overview']=[8,47,45]
    assets=read_json(ROOT/'assets/history/manifest.json');d['visual_assets']=[a for a in assets if a['id'] in ('goldsmith','adam-eve','erasmus','melencolia')]
    d['persons']=[dict(id='erasmus',name='Erasmo da Rotterdam',role='Umanista e studioso',period='1466/1469–1536',portrait='assets/history/erasmus.jpg',intro='Libri, lettere e amicizie collegano i centri della cultura europea.',events=['holbein']),dict(id='leonardo',name='Leonardo da Vinci',role='Artista e ingegnere',period='1452–1519',intro='Il viaggio in Francia mostra il ruolo delle corti nella mobilità degli artisti.')]
    d['events']=[event('goldsmith',1449,'Petrus Christus dipinge l’orefice','cultural_event',['R3']),event('printing',1455,'La Bibbia di Gutenberg','invention',['R4']),event('venice',1469,'Primo libro stampato a Venezia','cultural_event',['R5']),event('durer',1494,'Dürer parte per l’Italia','cultural_event',['R6']),event('adam',1504,'Adamo ed Eva','cultural_event',['R7']),event('leonardo',1516,'Leonardo si stabilisce in Francia','cultural_event',['R8']),event('holbein',1526,'Lettere per il viaggio di Holbein','cultural_event',['R9'])]
    d['scenes']=[
      scene(1,'Come viaggia un’idea?','map_overview',[1400,1420],"Una carta d’Europa può raccontare una storia senza seguire un esercito. Fra le città italiane, le Fiandre e le regioni tedesche circolano dipinti, libri, tecniche e persone. Il Rinascimento prende forma anche attraverso questi scambi. Non possiede una capitale unica, né una frontiera che separi improvvisamente il mondo vecchio da quello nuovo.|Per comprenderlo seguiremo alcune città e alcuni oggetti. Vedremo innovazioni nate in ambienti diversi incontrarsi, essere imitate e cambiare significato. La parola Rinascimento riunisce esperienze molteplici: la nostra mappa le collega, senza trasformarle nelle tappe obbligate di un progresso identico per tutti.",['R1','R2','R10'],location_ids=['florence','bruges','mainz','venice'],camera_end=[8,47,45],kicker='Una storia di relazioni',facts=['Città, botteghe e corti: una rete senza una frontiera unica.']),
      scene(2,'Firenze: la città come cantiere','city_focus',[1420,1440],"Il primo punto è Firenze. Nel Quattrocento, chiese, piazze e sedi delle corporazioni offrono agli artisti occasioni di lavoro e di confronto. Donatello opera dentro questo paesaggio urbano. Le sculture non sono pensate per sale di museo: rispondono a spazi, committenti e pubblici precisi.|Guardare una città significa allora riconoscere anche chi rende possibile un’opera. Risorse economiche, devozione e prestigio civico si intrecciano. Il richiamo all’antichità non cancella le funzioni religiose dell’arte. Le nuove forme nascono dentro istituzioni e pratiche già esistenti, mentre gli artisti sperimentano modi diversi di rappresentare corpi, emozioni e presenza umana.",['R1','R11'],location_ids=['florence','rome','venice'],camera_end=[11.4,44,12],kicker='Arte e spazio pubblico',facts=['Le opere rispondono a luoghi, committenti e funzioni.']),
      scene(3,'Bruges: osservare le cose','artwork',[1449,1449],"Spostiamoci a Bruges. Nel millequattrocentoquarantanove Petrus Christus dipinge un orefice nella sua bottega. Il metallo, il vetro, le stoffe e le superfici riflettenti fanno del quadro un esercizio di osservazione. L’immagine suggerisce un mondo di oggetti preziosi, lavoro specializzato e relazioni sociali.|L’identità esatta del protagonista e la funzione originaria del dipinto hanno suscitato interpretazioni diverse. Non occorre risolverle inventando una certezza. Possiamo invece vedere come la pittura a olio permetta trasparenze, dettagli e passaggi di luce. Anche qui si costruisce una nuova esperienza visiva, con soluzioni che avranno interesse ben oltre i Paesi Bassi.",['R2','R3'],asset_ids=['goldsmith'],event_ids=['goldsmith'],kicker='Un altro centro di innovazione',facts=['Petrus Christus, 1449. L’identificazione del committente resta discussa.']),
      scene(4,'La pagina diventa moltiplicabile','event_focus',[1454,1455],"A metà del Quattrocento, a Magonza, un cambiamento tecnico trasforma la produzione del libro. Gutenberg mette a punto un sistema di stampa con caratteri mobili metallici. La sua celebre Bibbia è realizzata negli anni intorno al millequattrocentocinquantacinque. È una svolta europea, non l’inizio universale di ogni forma di stampa.|Comporre, inchiostrare e ripetere la stessa pagina permette di produrre più esemplari di un testo. Servono però capitale, materiali, competenze e compratori. Il libro stampato non raggiunge immediatamente tutti. Amplia le possibilità di circolazione, ma non rende automaticamente alfabetizzata la società e non elimina il manoscritto dalla vita culturale.",['R4','R5'],event_ids=['printing'],kicker='Tecnica, lavoro, lettori',facts=['La stampa moltiplica gli esemplari. La diffusione della lettura resta diseguale.'],highlights=['Magonza · circa 1454–1455','Caratteri mobili metallici','Libri, competenze e investimenti']),
      scene(5,'Venezia: il crocevia dei libri','network_map',[1469,1490],"La stampa attraversa presto le Alpi. A Venezia il primo libro viene stampato nel millequattrocentosessantanove da Giovanni da Spira, proveniente dall’area tedesca. La città diventa un importante centro editoriale, alimentato da competenze mobili e collegamenti commerciali. Per capire questo sviluppo, il confine fra storia culturale e storia economica diventa poco utile.|Viaggiano i testi, ma anche stampatori, incisori e strumenti. Le relazioni tra il mondo tedesco e Venezia non sono una semplice esportazione italiana verso nord. La carta mostra qui legami fra centri, non un itinerario individuale documentato in ogni tappa. È la struttura dello scambio che ci interessa rendere visibile.",['R5'],location_ids=['mainz','venice','florence','nuremberg'],camera_end=[10.8,47.5,21],network={'nodes':[{'location_id':'mainz'},{'location_id':'venice'}],'edges':[{'from':'mainz','to':'venice','semantic':'technology_diffusion','sources':['R5'],'uncertain':True}]},kicker='Un centro editoriale europeo',facts=['Venezia, 1469: tecnici e reti commerciali sostengono la nuova editoria.']),
      scene(6,'Dürer attraversa le Alpi','animated_route',[1494,1495],"Un artista può essere esso stesso un collegamento fra mondi diversi. Albrecht Dürer nasce a Norimberga, città attiva nelle arti e nel commercio. Fra il millequattrocentonovantaquattro e il novantacinque visita l’Italia. Tornerà ancora, dieci anni più tardi. L’esperienza italiana arricchisce una formazione già radicata nelle botteghe del nord.|Non è il viaggio di un allievo privo di una propria cultura. Dürer osserva, confronta e seleziona. Il suo interesse per le proporzioni e per la teoria si intreccia con una straordinaria abilità nell’incisione. Nella nostra carta il percorso è schematico: documenta il rapporto fra i centri, senza pretendere di ricostruire ogni strada percorsa.",['R6'],location_ids=['nuremberg','venice'],camera_end=[11.2,47.5,16],movements=[dict(semantic='journey',points=[[11.08,49.45],[11.4,47.27],[11.12,46.07],[12.32,45.44]],sources=['R6'],uncertain=True)],kicker='Un artista fra Nord e Sud',facts=['Primo viaggio italiano: 1494–1495. Itinerario rappresentato in forma schematica.']),
      scene(7,'Un’incisione attraversa l’Europa','artwork',[1504,1504],"Nel millecinquecentoquattro Dürer incide Adamo ed Eva. Il soggetto biblico convive con un’attenta costruzione delle figure e con una varietà di superfici: corteccia, pelle, foglie e pelo degli animali. L’incisione richiede una precisione che trasforma piccoli segni in luce e materia.|A differenza di un dipinto destinato a un unico ambiente, una matrice può produrre più impressioni. L’immagine raggiunge luoghi nei quali l’artista non sarà mai presente. La circolazione delle stampe offre quindi un mezzo concreto per studiare e rielaborare invenzioni altrui. La diffusione culturale passa anche dalla possibilità di tenere, guardare e confrontare un foglio.",['R7','R6'],asset_ids=['adam-eve'],event_ids=['adam'],kicker='L’immagine riproducibile',facts=['Adamo ed Eva, 1504: il foglio moltiplica le occasioni di incontro con un’immagine.']),
      scene(8,'Scambi in entrambe le direzioni','comparison',[1505,1507],"La storia diventa più chiara se abbandoniamo l’idea di un’unica freccia. In Italia interessano le ricerche nordiche sul colore e sui dettagli. A nord delle Alpi vengono studiate opere, proporzioni e teorie italiane. I mercanti possono acquistare dipinti, gli artisti viaggiare, le stampe passare di mano.|Questi movimenti si sovrappongono e non producono copie identiche. Ogni ambiente modifica ciò che riceve secondo gusti, funzioni e richieste locali. Parlare di Rinascimento europeo significa riconoscere questa capacità di trasformazione. L’influenza non si misura come una conquista territoriale: una città può partecipare a più tradizioni, nello stesso momento, senza abbandonare del tutto le proprie.",['R2','R6','R10'],kicker='Una rete reciproca',facts=['Ricevere un’idea significa anche trasformarla.'],comparison=[{'title':'Dal Nord verso il Sud','text':'Pittura a olio, dettagli delle superfici, competenze tipografiche e incisorie.'},{'title':'Dal Sud verso il Nord','text':'Studio dell’antico, proporzioni, prospettiva e confronto diretto con le opere.'}]),
      scene(9,'Leonardo alla corte di Francia','animated_route',[1516,1519],"Le corti offrono un’altra via alla mobilità. Nel millecinquecentosedici Leonardo da Vinci si stabilisce in Francia, invitato da Francesco primo. Vive al Clos Lucé, vicino ad Amboise, negli ultimi anni della sua vita. Con lui si muovono opere, conoscenze e una reputazione costruita in una lunga carriera.|La presenza di un artista celebre serve anche al prestigio del sovrano. Disegno, architettura, ingegneria e spettacoli di corte possono incontrarsi nelle stesse commissioni. Leonardo muore nel millecinquecentodiciannove. Il suo soggiorno aiuta a vedere come il Rinascimento attraversi l’Europa attraverso rapporti personali e protezioni politiche, oltre che attraverso mercati e botteghe.",['R8'],location_ids=['rome','amboise'],camera_end=[6.5,46.4,26],movements=[dict(semantic='journey',points=[[12.5,41.9],[9.2,45.46],[6.2,45.4],[4.84,45.76],[.984,47.413]],sources=['R8'],uncertain=True)],kicker='Artisti e mecenati',facts=['Leonardo al Clos Lucé, 1516–1519. Collegamento schematico fra Italia e Francia.']),
      scene(10,'Erasmo: la forza delle relazioni','person_intro',[1526,1532],"Il ritratto di Erasmo realizzato da Holbein e dalla sua bottega, intorno al millecinquecentotrentadue, presenta un uomo di studio. Lo sguardo e la sobrietà dell’abito costruiscono un’identità intellettuale. Non siamo davanti a un generale o a un territorio: il protagonista è una rete di libri, lettere e amicizie.|Nel millecinquecentoventisei Erasmo aveva fornito a Holbein lettere di presentazione per amici in Inghilterra. Un rapporto personale poteva aprire porte in un’altra città. La cultura umanistica vive anche di questi strumenti quotidiani. Il ritratto rende visibile la persona; la corrispondenza aiuta a capire come la sua influenza superasse il luogo in cui abitava.",['R9'],person_ids=['erasmus'],event_ids=['holbein'],kicker='La repubblica delle lettere',facts=['Una lettera di presentazione può collegare artisti, studiosi e nuovi committenti.']),
      scene(11,'Le tecniche cambiano mestiere','document',[1532,1545],"Le innovazioni non viaggiano soltanto da una regione all’altra. Possono passare da un mestiere a un altro. L’acquaforte, usata nella decorazione delle armature, entra nella produzione di immagini su carta. Fra la fine del Quattrocento e il Cinquecento, artisti di diverse regioni europee sperimentano il procedimento.|Questa trasformazione invita a guardare oltre i nomi più celebri. Materiali, artigiani e conoscenze pratiche sono parte della storia culturale. Il foglio che osserviamo è invece un’incisione a bulino di Dürer: non un esempio di acquaforte. Accostare le tecniche serve a distinguere procedimenti diversi, senza confondere ogni stampa con lo stesso modo di lavorare.",['R10','R6'],asset_ids=['melencolia'],kicker='Tecniche distinte',facts=['Melencolia I, 1514: incisione a bulino. Mostrata per confronto, non come acquaforte.']),
      scene(12,'Un’Europa di scambi','summary',[1545,1550],"Alla fine del percorso non troviamo una carta interamente colorata dalla stessa cultura. Troviamo centri differenti, collegati da persone, oggetti e competenze. Firenze, Bruges, Venezia, Norimberga, Basilea e le corti francesi partecipano a processi che non avanzano con il medesimo ritmo.|Il Rinascimento non si esaurisce in un elenco di capolavori. È anche una storia di luoghi di lavoro, committenze, tecniche e possibilità di comunicazione. Le differenze non scompaiono attraverso gli scambi: spesso diventano la ragione stessa del loro interesse. Per raccontare questa Europa servono dunque mappe, ma anche volti e opere: prove concrete di come un’idea possa cambiare incontrando un altro mondo.",['R1','R2','R5','R9','R10'],kicker='Ciò che resta',facts=['Persone, opere e tecniche trasformano le relazioni fra le città.'],highlights=['Più centri di innovazione','Scambi reciproci e selettivi','Tempi e accessi diseguali'])]
    d['editorial_notes']+=['Non si assume una diffusione unidirezionale da Firenze. Le date dei quadri sono distinte dalla data degli eventi raccontati.','Melencolia I è incisione a bulino, mostrata come confronto con l’acquaforte.','Erasmo: anno di nascita controverso, 1466/1469; ritratto datato circa 1532.']
    d['pronunciation']={'Dürer':'Dùrer','Holbein':'Hòlbein','Clos Lucé':'Clò Lusé','Bruges':'Brug','Erasmo':'Erasmo'}
    d['target_minutes']=7
    d['scenes'][1]['location_ids']=['florence','venice']
    d['scenes'][4]['location_ids']=['mainz','venice','nuremberg']
    d['scenes'][5]['camera_end']=[11.2,47,22]
    d['scenes'][8]['camera_end']=[6.5,44.8,33]
    d['scenes'][8]['label_offsets']={'rome':[50,-27]}
    import re
    d['voice_custom_chunks']={f'06:{i}':re.split(r'(?<=[,.!?;:])\s+',l) for i,l in enumerate(d['scenes'][5]['lines'])}
    for a in d['visual_assets']:a['title']={'goldsmith':'Un orefice nella sua bottega','adam-eve':'Adamo ed Eva','erasmus':'Erasmo da Rotterdam','melencolia':'Melencolia I'}[a['id']]
    return d

def roman():
    src=[source('ROM1','Met — The Roman Republic','https://www.metmuseum.org/essays/the-roman-republic','Conquiste e diplomazia, province e crisi della repubblica.'),source('ROM2','Met — The Roman Empire','https://www.metmuseum.org/essays/the-roman-empire-27-b-c-393-a-d','Augusto, trasformazione istituzionale e massima espansione sotto Traiano.'),source('ROM3','British Museum — Introduction to ancient Rome','https://www.britishmuseum.org/exhibitions/nero-man-behind-myth/introduction-to-ancient-rome','Estensione imperiale e lettura critica delle mappe.'),source('ROM4','Polibio, Storie I–III','https://penelope.uchicago.edu/Thayer/E/Roman/Texts/Polybius/1*.html','Testo antico: guerre puniche e Sicilia; confronto con la cronologia museale.')]
    d=base('impero-romano','Roma — Dal potere italiano all’impero','territorial_expansion',[-264,117],3,src,[loc('rome','Roma',12.5,41.9),loc('carthage','Cartagine',10.32,36.85),loc('alexandria','Alessandria',29.92,31.2),loc('athens','Atene',23.73,37.98),loc('lyon','Lugdunum',4.84,45.76)])
    d['overview']=[18,40,65];d['entities']=[dict(id='rome',name='Roma',color=[228,153,96])]
    polys={'italy':[[8,44],[12,44.7],[15.8,41.6],[17.4,40.1],[16.1,38.1],[14.8,40],[12,42]],'sicily':[[12.4,38],[15.6,38.3],[15.1,36.7],[13,37]],'africa':[[8,36.7],[11,37],[11.3,34],[8,34]],'greece':[[21,40.5],[24.5,40.5],[24,37],[21.5,36.8]],'gaul':[[-.8,43.3],[6.5,43.4],[8,48.3],[4.5,50.8],[-3.8,48]],'egypt':[[29.4,31.4],[32.5,31.2],[33,27],[31,24],[29.7,28]],'dacia':[[22,45],[27,45],[26,48],[23,47.6]],'mesopotamia':[[38,37],[43,37],[46,32],[43,31.5]]}
    # Deliberately regional masks: these are not reconstructed frontier polygons.
    d['visual_layers']=[dict(id=name,kind='territory',label=label,color=[228,153,96],schematic=True,sources=refs,states=[dict(year=year,polygons=[polys[name]])]) for name,label,year,refs in [('italy','Italia e alleati',-264,['ROM1']),('sicily','Sicilia',-241,['ROM4']),('africa','Africa',-146,['ROM1']),('greece','Grecia',-146,['ROM1']),('gaul','Gallia',-50,['ROM1']),('egypt','Egitto',-30,['ROM2']),('dacia','Dacia',106,['ROM2']),('mesopotamia','Conquiste orientali',116,['ROM2'])]]
    d['visual_layers'][-1]['states'][0]['contested']=True
    d['events']=[event('sicily',-241,'Sicilia: prima provincia oltremare','territorial_change',['ROM4']),event('carthage',-146,'Distruzione di Cartagine','territorial_change',['ROM1']),event('augustus',-27,'Ottaviano diventa Augusto','political_event',['ROM1']),event('trajan',117,'Morte di Traiano','death',['ROM2'])]
    d['scenes']=[scene(1,'Roma guarda oltre l’Italia','territorial_change',[-264,-241],"Nel duecentosessantaquattro avanti Cristo Roma è una potenza italiana. Il suo dominio non è uno stato uniforme: comprende cittadini, comunità subordinate e alleati. La guerra contro Cartagine apre una lunga contesa per il controllo del Mediterraneo occidentale.|Dopo la prima guerra punica, conclusa nel duecentoquarantuno, la Sicilia diventa il primo possedimento provinciale romano oltre la penisola. La nostra carta evidenzia regioni indicative: non pretende di disegnare ogni confine né di equiparare tutti gli abitanti nella stessa condizione giuridica.",['ROM1','ROM4'],location_ids=['rome','carthage'],camera_end=[14,39.8,27],kicker='Cittadini, alleati, province',facts=['264–241 a.C. · Dall’Italia alla Sicilia.'],map_note='Regioni schematiche · non confini storici esatti'),scene(2,'Un Mediterraneo trasformato','territorial_change',[-240,-146],"Le vittorie non seguono un progetto perfettamente stabilito fin dall’inizio. Guerre, rivalità e accordi ampliano progressivamente il controllo romano. Nel centoquarantasei avanti Cristo Cartagine viene distrutta; anche il mondo greco è sottoposto a una crescente imposizione romana.|La mappa conserva le regioni già evidenziate mentre ne aggiunge altre. Il colore indica una tappa del racconto, non una conquista istantanea di ogni punto. Amministrare territori lontani richiede governatori, eserciti e rapporti con le élite locali. Le risorse ottenute modificano profondamente anche la società romana.",['ROM1'],location_ids=['rome','carthage','athens'],camera_end=[18,39,40],event_ids=['carthage'],kicker='Conquiste e amministrazione',facts=['Il potere cresce per guerre e diplomazia.'],map_note='Campione di regioni · non superficie totale dell’impero'),scene(3,'Conquiste e guerre civili','territorial_change',[-145,-27],"Nel primo secolo avanti Cristo la conquista della Gallia e l’assoggettamento dell’Egitto ampliano ancora gli orizzonti di Roma. Contemporaneamente, il sistema repubblicano attraversa crisi sociali e guerre civili. Il successo esterno non garantisce stabilità interna.|Dopo l’assassinio di Cesare, Ottaviano prevale sui rivali. Nel ventisette avanti Cristo riceve il titolo di Augusto. La trasformazione politica non coincide con l’inizio di tutte le conquiste: un vasto dominio esisteva già sotto la repubblica. Separare questi due processi evita di confondere l’impero territoriale con il governo personale degli imperatori.",['ROM1','ROM2'],location_ids=['rome','lyon','alexandria'],camera_end=[16,41,60],kicker='Territorio e istituzioni',facts=['L’impero territoriale precede il principato di Augusto.'],map_note='Campione di regioni · non superficie totale dell’impero'),scene(4,'Il massimo non è un equilibrio','territorial_change',[-26,117],"Sotto gli imperatori proseguono espansioni e consolidamenti. Traiano, al potere fra il novantotto e il centodiciassette dopo Cristo, conquista la Dacia e conduce campagne in Oriente. Alla sua morte il dominio romano ha raggiunto la massima estensione convenzionalmente rappresentata negli atlanti.|Ma il controllo non è ovunque stabile. Le conquiste orientali saranno in parte abbandonate da Adriano. Un’area colorata non basta a raccontare il governo effettivo: occorrono strade, guarnigioni, accordi e risorse. Per questo la massima estensione non deve essere scambiata per un confine duraturo.",['ROM2','ROM3'],location_ids=['rome','athens','alexandria'],camera_end=[22,40,72],kicker='Espansione e fragilità',facts=['117 d.C. · Il massimo territoriale non implica controllo stabile.'],map_note='Regioni indicative · conquiste orientali contestate'),scene(5,'Che cosa significa dominare?','comparison',[117,117],"Abbiamo seguito alcune tappe di quasi quattro secoli. Il risultato non è soltanto una superficie più grande. Cambiano istituzioni, rapporti sociali e possibilità di collegamento. Roma esercita il potere in modi diversi, negoziando, amministrando e ricorrendo alla forza.|La scelta di mostrare regioni schematiche rende leggibile la successione, ma non fornisce una misura dell’area imperiale. Per confrontare superfici servirebbero dati geografici storici omogenei. La conclusione è politica oltre che geografica: espandersi e governare sono problemi collegati, senza essere la stessa cosa.",['ROM1','ROM2','ROM3'],kicker='Una distinzione necessaria',facts=['Conquistare, amministrare e integrare sono processi distinti.'],comparison=[dict(title='Estensione',text='Quali territori sono rivendicati o conquistati in una determinata fase?'),dict(title='Controllo',text='Con quali istituzioni, risorse, accordi e costi viene esercitato il potere?')])]
    d['editorial_notes']+=['I poligoni evidenziano soltanto alcune regioni pertinenti, non la superficie totale né le frontiere imperiali. Nessun grafico di km² viene derivato da questi poligoni.']
    return d

def migrations():
    src=[source('M1','University of Texas — Gothic historical context','https://lrc.la.utexas.edu/eieol/gotol/90','Ingresso dei Goti nel 376, rapporti con Roma e conflitti successivi.'),source('M2','Met — Migration Art A.D. 300–800','https://resources.metmuseum.org/resources/metpublications/pdf/Migration_Art_AD_300_800.pdf','Movimenti e manufatti della tarda antichità; Vandali in Africa e Cartagine nel 439. Terminologia etnica trattata criticamente.'),source('M3','Guy Halsall - Barbarian Migrations and the Roman West, 376-568','https://assets.cambridge.org/97805214/34911/frontmatter/9780521434911_frontmatter.pdf','Frontespizio e presentazione editoriale consultati: quadro del dibattito sui rapporti tra crisi romana, migrazioni e identita. Volume non consultato integralmente; non usato per datare singoli eventi.')]
    d=base('migrazioni-germaniche','Migrazioni — Attraversare il mondo romano','migration',[376,476],3,src,[loc('danube','Basso Danubio',27.5,44),loc('rome','Roma',12.5,41.9),loc('toulouse','Tolosa',1.44,43.6),loc('gibraltar','Gibilterra',-5.35,36.14),loc('carthage','Cartagine',10.32,36.85),loc('rhine','Reno',8.2,50)])
    d['overview']=[10,43,58];d['entities']=[dict(id='goths',name='Gruppi gotici',color=[129,208,186]),dict(id='vandals',name='Vandali e alleati',color=[197,173,231])]
    d['events']=[event('cross',376,'Gruppi gotici attraversano il Danubio','migration',['M1']),event('rome',410,'Sacco di Roma di Alarico','battle',['M2']),event('africa',429,'Passaggio dei Vandali in Africa','migration',['M2']),event('carthage',439,'Presa di Cartagine','territorial_change',['M2']),event('end',476,'Fine dell’impero romano d’Occidente','political_event',['M2'])]
    d['scenes']=[scene(1,'Chi si mette in movimento?','map_overview',[376,376],"Le cosiddette migrazioni barbariche non sono il viaggio di popoli immutabili sopra una carta vuota. Uomini, donne e gruppi armati attraversano un mondo già abitato, governato e collegato. I nomi usati dalle fonti romane non descrivono necessariamente comunità omogenee.|Nel trecentosettantasei gruppi gotici chiedono di attraversare il Danubio. La pressione degli Unni è una parte del contesto; contano anche le decisioni romane e le condizioni dell’accoglienza. Raccontare questi movimenti richiede di distinguere migrazione, insediamento, servizio militare e guerra, senza attribuire a ogni percorso il significato automatico di invasione.",['M1','M2'],location_ids=['danube','rome','rhine'],camera_end=[14,46,53],kicker='Gruppi e identità in trasformazione',facts=['Un movimento di popolazione non equivale automaticamente a un attacco.']),scene(2,'Attraversare il Danubio','animated_route',[376,382],"Il passaggio del fiume non risolve la crisi. Le relazioni con le autorità imperiali peggiorano; le difficoltà materiali e gli abusi contribuiscono al conflitto. Nel trecentosettantotto, ad Adrianopoli, l’esercito dell’imperatore Valente subisce una grave sconfitta.|Gli accordi successivi mostrano che guerra e negoziato rimangono intrecciati. I gruppi entrati nell’impero non seguono una sola traiettoria già decisa. Le linee sulla carta indicano direzioni generali e non numeri di persone: le fonti non permettono un conteggio preciso e omogeneo per tutte le fasi del movimento.",['M1'],location_ids=['danube','rome'],camera_end=[24,43,34],movements=[dict(semantic='migration',points=[[28.5,45.5],[27.5,44],[26.5,42]],sources=['M1'],uncertain=True)],kicker='Dall’ingresso al conflitto',facts=['376–382 · Attraversamento, crisi e negoziato.']),scene(3,'Nuovi itinerari, nuovi accordi','animated_route',[400,418],"All’inizio del quinto secolo, le vicende dei gruppi gotici si intrecciano con le lotte politiche imperiali. Nel quattrocentodieci Alarico saccheggia Roma. È un evento traumatico, ma non coincide con la scomparsa immediata dell’impero d’Occidente.|Successivamente, gruppi visigoti si stabiliscono nella Gallia sudoccidentale. Il percorso unisce episodi differenti, distanti nel tempo: spostamento di persone, operazioni militari e insediamento non sono la stessa azione. Le identità politiche si ricompongono attraverso alleanze e leadership. Per questo la narrazione non presenta una freccia continua come se fosse un unico piano seguito per decenni.",['M2'],location_ids=['rome','toulouse'],camera_end=[7.5,43.4,31],movements=[dict(semantic='migration',points=[[12.5,41.9],[10,44],[5.4,43.3],[1.44,43.6]],sources=['M2'],uncertain=True)],kicker='410 non è la fine dell’impero',facts=['Conflitto e successivo insediamento appartengono a fasi diverse.']),scene(4,'I Vandali verso l’Africa','animated_route',[429,439],"Un altro itinerario attraversa la penisola iberica e raggiunge l’Africa settentrionale. Nel quattrocentoventinove i Vandali e i loro alleati passano il mare. Nel quattrocentotrentanove prendono Cartagine, nodo decisivo del Mediterraneo romano.|Questa vicenda non è identica a quella dei Goti. Cambiano le leadership, le opportunità politiche e i territori coinvolti. Due colori distinguono i gruppi senza assegnare loro una consistenza numerica. La perdita di regioni africane ha conseguenze sulle risorse dell’impero occidentale e mostra quanto i movimenti di popolazione possano trasformarsi in nuovi poteri territoriali.",['M2'],location_ids=['gibraltar','carthage'],camera_end=[3,36.5,40],movements=[dict(semantic='migration',color=[197,173,231],points=[[-5.35,36.14],[-5.5,35.75],[-1,35.5],[3.1,36.7],[7.75,36.9],[10.32,36.85]],sources=['M2'],uncertain=True)],kicker='Un percorso distinto',facts=['429: passaggio in Africa. 439: presa di Cartagine.']),scene(5,'Trasformazioni, non sostituzione totale','summary',[439,476],"Nel corso del quinto secolo nuovi regni si consolidano entro territori prima imperiali. Il quattrocentosettantasei resta una data convenzionale per la fine dell’impero romano d’Occidente, mentre l’impero d’Oriente continua a esistere. Le popolazioni locali non scompaiono dal paesaggio.|Gli oggetti, le istituzioni e le pratiche mostrano incontri, continuità e trasformazioni. Il peso relativo delle migrazioni, delle crisi interne e delle guerre resta oggetto di discussione storiografica. Una carta utile non cancella questa complessità: distingue le tappe conosciute, segnala i percorsi schematici e lascia aperto ciò che le fonti non consentono di misurare.",['M1','M2'],kicker='Una tarda antichità plurale',facts=['Le identità si trasformano; le comunità locali continuano a partecipare alla storia.'],highlights=['Movimenti e negoziati','Nuovi regni e continuità','Numeri e itinerari spesso incerti'])]
    return d

def silk():
    src=[source('S1','UNESCO — About the Silk Roads','https://www.unesco.org/en/silk-roads/about-silk-roads','Reti terrestri e marittime, pluralità delle merci e diffusione di conoscenze. Il nome moderno è retrospettivo.'),source('S2','UNESCO World Heritage — Chang’an–Tianshan Corridor','https://whc.unesco.org/en/list/1442/','Rete di corridoi, cronologia generale e ambienti attraversati.'),source('S3','UNESCO — Cities along the Silk Roads','https://en.unesco.org/silkroad/silk-road-themes/cities-silk-roads','Città come mercati, luoghi di riposo e scambio culturale.'),source('S4','UNESCO — Exchange of Technical Knowledge','https://en.unesco.org/silkroad/content/did-you-know-exchange-technical-knowledge-used-craft-silk-roads-goods','Scambio di tecniche, merci comuni e beni di prestigio.')]
    places=[loc('changan','Chang’an',108.94,34.34),loc('dunhuang','Dunhuang',94.66,40.14),loc('samarkand','Samarcanda',66.98,39.65),loc('bukhara','Bukhara',64.43,39.77,offset=[-45,-28]),loc('venice','Venezia',12.32,45.44),loc('hormuz','Hormuz',56.45,27.1),loc('calicut','Calicut',75.78,11.25),loc('quanzhou','Quanzhou',118.59,24.91)]
    d=base('via-della-seta','Vie della Seta — Una rete di mondi','trade_network',[-200,1500],3,src,places);d['overview']=[67,35,137];d['atlas']='assets/geography/atlas-history/atlas.json'
    d['events']=[event('han',-200,'Scambi eurasiatici nell’epoca Han','trade_route_change',['S1','S2']),event('hubs',700,'Città e corridoi dell’Asia centrale','economic_event',['S2']),event('sea',1200,'Reti marittime dell’Oceano Indiano','trade_route_change',['S1'])]
    land=[dict(from_='changan',to='dunhuang',points=[[108.94,34.34],[103.8,36.1],[98.5,39.7],[94.66,40.14]]),dict(from_='dunhuang',to='samarkand',points=[[94.66,40.14],[89,42],[81,43],[75,42],[69,41],[66.98,39.65]])]
    edges=[{'from':e['from_'],'to':e['to'],'points':e['points'],'semantic':'trade','uncertain':True,'sources':['S2']} for e in land]
    d['scenes']=[scene(1,'Non una strada, ma molte reti','network_map',[-200,200],"La Via della Seta non è una strada unica da percorrere tutta in una volta. Il nome, moderno, riunisce reti di scambio sviluppate in epoche diverse attraverso l’Eurasia. Vie terrestri e collegamenti marittimi mettono in relazione comunità lontane, spesso attraverso numerosi intermediari.|La seta è un bene importante, ma non esaurisce la storia. Viaggiano alimenti, oggetti, tecniche e conoscenze. La carta mostra alcuni nodi e corridoi, senza attribuire loro una capacità commerciale costante. Seguire le reti significa osservare come i collegamenti cambiano e come ogni città partecipa a scambi più vicini oltre che a quelli lontani.",['S1','S2'],location_ids=['changan','dunhuang','samarkand','venice'],camera_end=[66,38,140],network={'nodes':[{'location_id':p} for p in ['changan','dunhuang','samarkand']],'edges':edges},kicker='Il nome è moderno',facts=['Una rete di corridoi terrestri e marittimi, non una singola strada.']),scene(2,'Le città rendono possibile il viaggio','city_focus',[200,700],"Le distanze contano, ma contano altrettanto i luoghi nei quali fermarsi. Le città offrono mercati, acqua, ospitalità e occasioni per cambiare animali e mediatori. Samarcanda e Bukhara partecipano a questo paesaggio di contatti, insieme a molti altri centri dell’Asia centrale.|Non tutti i mercanti devono raggiungere l’estremità opposta del continente. Gli scambi possono procedere per segmenti. Una merce passa di mano e acquista nuovi significati. I nodi della mappa non indicano città della stessa grandezza: esprimono la funzione di collegamento. Per confrontarne popolazioni e traffici occorrerebbero serie storiche che qui non possediamo.",['S3'],location_ids=['samarkand','bukhara','dunhuang'],camera_end=[78,40,55],network={'nodes':[{'location_id':p} for p in ['samarkand','bukhara']],'edges':[{'from':'bukhara','to':'samarkand','semantic':'trade','sources':['S3']}]},kicker='Mercati e intermediari',facts=['I viaggi possono essere segmentati. I nodi non rappresentano un volume di commercio.']),scene(3,'Oltre la seta','comparison',[700,1000],"Gli oggetti di lusso attirano l’attenzione, ma gli scambi comprendono anche prodotti utili nella vita quotidiana. I beni cambiano insieme ai bisogni e alle disponibilità delle comunità. Non esiste un carico standard valido per ogni epoca e per ogni segmento della rete.|Accanto ai prodotti circolano saperi pratici. Chi conosce una tecnica può essere richiesto lontano dal luogo in cui l’ha appresa. Le informazioni viaggiano con persone reali e possono essere adattate a nuovi materiali e nuovi mercati. Per questo il confronto fra merci e conoscenze aiuta più di una freccia che sembri misurare una quantità inesistente.",['S1','S4'],kicker='Cose e conoscenze',facts=['Le reti trasferiscono prodotti e competenze.'],comparison=[dict(title='Merci',text='Seta, alimenti, materie prime e beni di prestigio; combinazioni diverse nel tempo.'),dict(title='Conoscenze',text='Tecniche artigianali, lingue, idee e pratiche che cambiano attraverso gli incontri.')]),scene(4,'Anche il mare è una strada','animated_route',[1000,1300],"L’Oceano Indiano è parte essenziale di questo mondo connesso. Porti, naviganti e mercanti collegano regioni asiatiche e occidentali attraverso rotte marittime. La nostra linea azzurra distingue il mare dai corridoi terrestri: non rappresenta un viaggio unico documentato da un estremo all’altro.|Le reti dipendono da approdi, condizioni ambientali e poteri politici. I centri acquistano o perdono importanza; i percorsi vengono adattati. La storia non è una semplice sostituzione della terra con il mare. Collegamenti diversi possono coesistere e sostenersi. Per comprendere gli scambi bisogna guardare alle connessioni fra retroterra, città e porti.",['S1','S3'],location_ids=['hormuz','calicut','quanzhou'],camera_end=[87,23,106],movements=[dict(semantic='sea_trade',points=[[56.45,27.1],[61,23],[68,16],[75.78,11.25],[79,6],[85,5],[94,5],[99,2],[104,1],[109,12],[116,22],[118.59,24.91]],sources=['S1'],uncertain=True)],kicker='Reti terrestri e marittime',facts=['Rotta indicativa fra porti: non un itinerario individuale né una misura del traffico.']),scene(5,'Una storia fatta di intermediari','summary',[1300,1500],"Le Vie della Seta permettono di raccontare la storia da un punto di vista diverso: quello delle relazioni. Gli imperi contano, ma non esauriscono ciò che si muove tra le loro frontiere. Città, mercanti, artigiani e viaggiatori costruiscono collegamenti che nessuna singola autorità controlla per sempre.|Le reti cambiano senza sparire tutte nello stesso momento. Il loro valore storico non dipende da un percorso perfetto tracciato sulla carta. Sta negli incontri, negli adattamenti e nella trasmissione di beni e conoscenze. La mappa diventa così una domanda: chi collega un luogo all’altro, e quali trasformazioni rende possibili quel collegamento?",['S1','S2','S3','S4'],kicker='Una geografia di relazioni',facts=['Nodi, intermediari e percorsi mutano nel tempo.'],highlights=['Più vie e più epoche','Terra e mare collegati','Scambi materiali e culturali'])]
    return d

def napoleon():
    src=[source('N1','Fondation Napoléon — Napoléon Ier, biographie','https://www.napoleon.org/histoire-des-2-empires/biographies/napoleon-ier-1769-1821-empereur/','Cronologia della vita; formazione, carriera, politica ed esilio.'),source('N2','Fondation Napoléon — Timeline Consulate / First Empire','https://www.napoleon.org/en/young-historians/napodoc/timeline-consulate1st-french-empire/','Colpo di stato, impero, campagne, abdicazioni, esilio e morte.'),source('N3','Fondation Napoléon — Jeunesse 1769–1793','https://www.napoleon.org/histoire-des-2-empires/dossiers-thematiques/1769-1793-la-jeunesse-dun-futur-empereur/','Contesto corso, formazione e Rivoluzione francese.')]
    d=base('napoleone-biografia','Napoleone — Una vita fra rivoluzione e impero','biography',[1769,1821],3,src,[loc('ajaccio','Ajaccio',8.74,41.92),loc('brienne','Brienne',4.53,48.39),loc('paris','Parigi',2.35,48.86),loc('toulon','Tolone',5.93,43.12),loc('milan','Milano',9.19,45.46),loc('moscow','Mosca',37.62,55.75)])
    d['overview']=[12,47,45];d['persons']=[dict(id='napoleon',name='Napoleone Bonaparte',role='Militare, primo console, imperatore',period='1769–1821',portrait='assets/portraits/napoleon.jpg',intro='Una carriera intrecciata alla Rivoluzione francese, alle istituzioni e alle guerre europee.')]
    d['events']=[event('birth',1769,'Nascita ad Ajaccio','birth',['N1']),event('consul',1799,'Colpo di stato del 18 brumaio','political_event',['N2']),event('crown',1804,'Incoronazione imperiale','coronation',['N2']),event('russia',1812,'Campagna di Russia','battle',['N2']),event('waterloo',1815,'Waterloo e seconda abdicazione','battle',['N2']),event('death',1821,'Morte a Sant’Elena','death',['N2'])]
    d['scenes']=[scene(1,'Un ragazzo corso','person_intro',[1769,1779],"Napoleone Bonaparte nasce ad Ajaccio nel millesettecentosessantanove, poco dopo il passaggio della Corsica sotto il potere francese. La sua famiglia appartiene alla piccola nobiltà e cerca opportunità attraverso l’istruzione. Il futuro imperatore entra nella storia da una periferia recentemente acquisita.|La biografia non deve trasformare l’infanzia in un destino già scritto. Le borse di studio e la formazione militare gli aprono possibilità concrete. Il contesto corso e, più tardi, la Rivoluzione francese contribuiscono a cambiare il campo delle sue scelte. Il ritratto dell’uomo adulto introduce una vita da ricostruire, non una leggenda inevitabile.",['N1','N3'],person_ids=['napoleon'],kicker='Origini e possibilità',facts=['Ajaccio, 1769. Il contesto precede il mito.']),scene(2,'Formazione e Rivoluzione','animated_route',[1779,1793],"Dalla Corsica Napoleone raggiunge la Francia continentale per studiare. Passa per Brienne e per la scuola militare di Parigi, quindi diventa ufficiale d’artiglieria. L’istruzione tecnica sarà una risorsa della sua carriera, insieme alle relazioni e alle occasioni politiche.|La Rivoluzione sconvolge l’ordine nel quale si è formato. Nel millesettecentonovantatré, a Tolone, la sua azione contribuisce al successo repubblicano e gli vale una promozione. Sulla carta seguiamo luoghi di formazione e attività: questo spostamento personale non è disegnato come un attacco. La carriera dipende da decisioni individuali dentro una crisi collettiva.",['N1','N3'],location_ids=['ajaccio','brienne','paris','toulon'],camera_end=[5.5,44.7,45],movements=[dict(semantic='journey',points=[[8.74,41.92],[4.53,48.39],[2.35,48.86],[5.93,43.12]],sources=['N1'],uncertain=True)],kicker='Dalle scuole all’artiglieria',facts=['Luoghi selezionati della formazione; collegamento schematico.']),scene(3,'Dal generale al sovrano','timeline',[1796,1804],"Le campagne d’Italia accrescono la notorietà di Bonaparte. La fama militare si combina con l’ambizione politica. Nel millesettecentonovantanove il colpo di stato del diciotto brumaio apre il Consolato; nel milleottocentoquattro Napoleone diventa imperatore.|La cronologia rende visibili passaggi che una mappa da sola non spiegherebbe. Cambiano cariche, istituzioni e forme di legittimazione. Il nuovo potere conserva alcuni risultati della Rivoluzione mentre concentra l’autorità. Alleati, familiari e collaboratori partecipano al sistema. La biografia deve guardare anche a queste relazioni, senza attribuire ogni trasformazione alla volontà di un singolo uomo.",['N1','N2'],event_ids=['consul','crown'],kicker='Carriera e istituzioni',facts=['1799: Consolato. 1804: impero.']),scene(4,'Successi, limiti e sconfitta','comparison',[1804,1815],"Il potere napoleonico modifica una parte dell’Europa attraverso guerre, amministrazione e alleanze. La sua capacità di organizzare lo stato convive con la coercizione e con il costo umano dei conflitti. Le vittorie non eliminano gli avversari né garantiscono risorse illimitate.|La campagna di Russia del milleottocentododici è una svolta disastrosa. Seguono nuove sconfitte e la prima abdicazione. Dopo il ritorno dall’Elba, Waterloo nel milleottocentoquindici chiude i Cento Giorni. Confrontare risultati e costi aiuta a evitare tanto il racconto celebrativo quanto una spiegazione ridotta a un solo errore finale.",['N1','N2'],kicker='Risultati e costi',facts=['L’espansione del potere produce anche resistenze e vulnerabilità.'],comparison=[dict(title='Costruire il potere',text='Istituzioni, collaboratori, amministrazione, prestigio e alleanze.'),dict(title='Sostenere il potere',text='Guerre, risorse, coercizione, opposizioni e logoramento.')]),scene(5,'Sant’Elena e la memoria','summary',[1815,1821],"Dopo la seconda abdicazione Napoleone viene esiliato a Sant’Elena, nell’Atlantico meridionale. Muore il cinque maggio del milleottocentoventuno. Negli anni dell’esilio partecipa alla costruzione della propria memoria attraverso il racconto della sua esperienza.|La biografia continua dunque anche nella disputa sull’eredità. Le istituzioni e le guerre, l’autoritarismo e la mobilità sociale, la leggenda e le testimonianze offrono prospettive differenti. Comprendere una vita storica significa distinguere ciò che il protagonista volle dire di sé da ciò che altre fonti permettono di ricostruire. Le mappe mostrano gli spostamenti; le scelte e le conseguenze richiedono una narrazione più ampia.",['N1','N2'],kicker='Vita, memoria, interpretazione',facts=['5 maggio 1821 · Morte a Sant’Elena.'],highlights=['Esperienza e autorappresentazione','Istituzioni e costi delle guerre','Un’eredità discussa'])]
    return d

def main():
    for fn in [renaissance,roman,migrations,silk,napoleon]:
        d=fn();validate_document(d)
        words=sum(len(l.split()) for s in d['scenes'] for l in s['lines'])
        write_json(ROOT/'documentaries'/d['slug']/'documentary.json',d)
        print(d['slug'],words,'words',len(d['scenes']),'scenes',flush=True)
    write_json(ROOT/'documentaries/via-della-seta/geography.json',dict(bounds=[-15,-6,145,72],patches={},terrain_zoom=8,output='assets/geography/atlas-history'))

if __name__=='__main__':main()
